def create_anatomy_sections(apps, schema_editor):
    Subject = apps.get_model("bank", "Subject")
    SubjectSection = apps.get_model("bank", "SubjectSection")
    subject = Subject.objects.filter(slug="anatomy").first()
    if subject is None:
        subject = Subject.objects.filter(name__iexact="Anatomy").first()
    if subject is None:
        return

    for order, (name, slug) in enumerate([
        ("Embryology", "embryology"),
        ("Histology", "histology"),
        ("Gross Anatomy", "gross-anatomy"),
    ]):
        SubjectSection.objects.get_or_create(
            subject=subject, slug=slug,
            defaults={"name": name, "order": order},
        )


